//! Raw audio files (AC-3, E-AC-3, FLAC, DTS, TrueHD, MLP, WAV, RF64, Wave64, ADTS). The packet list must equal
//! `ffprobe -show_packets` (offset, size, timestamp, duration, key flag). Fixtures are generated by
//! `tests/rawfixtures/generate.sh` (git-ignored); files and ffprobe that are absent skip their test.

use aether_demux::{ByteSource, Container, Demuxer, FileSource, PacketRef, SliceSource, TrackKind};
use std::cell::Cell;
use std::process::Command;

const LAB: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../test-media");

fn fixture(name: &str) -> String {
    format!("{}/tests/rawfixtures/{name}", env!("CARGO_MANIFEST_DIR"))
}

struct Counting<'a> {
    inner: &'a FileSource,
    bytes: Cell<u64>,
}
impl ByteSource for Counting<'_> {
    fn len(&self) -> u64 {
        self.inner.len()
    }
    fn read_at(&self, offset: u64, buf: &mut [u8]) -> Result<usize, String> {
        let n = self.inner.read_at(offset, buf)?;
        self.bytes.set(self.bytes.get() + n as u64);
        Ok(n)
    }
}

#[derive(Debug)]
struct Probe {
    pts_s: f64,
    dur_s: f64,
    size: u32,
    pos: u64,
    key: bool,
}

fn ffprobe(path: &str) -> Option<Vec<Probe>> {
    let out = Command::new("ffprobe").args(["-v", "error", "-show_packets", "-select_streams", "a:0", "-of", "compact", path]).output().ok()?;
    if !out.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    let mut v = Vec::new();
    for line in text.lines().filter(|l| l.starts_with("packet|")) {
        let get = |k: &str| line.split('|').find_map(|f| f.strip_prefix(&format!("{k}="))).unwrap();
        v.push(Probe {
            pts_s: get("pts_time").parse().unwrap(),
            dur_s: get("duration_time").parse().unwrap(),
            size: get("size").parse().unwrap(),
            pos: get("pos").parse().unwrap(),
            key: get("flags").starts_with('K'),
        });
    }
    Some(v)
}

fn have(path: &str) -> bool {
    std::path::Path::new(path).exists()
}

/// (file, container codec, engine codec string, channels, rate)
type Case = (String, &'static str, &'static str, u32, u32);

fn cases() -> Vec<Case> {
    let lab = |n: &str| format!("{LAB}/{n}");
    vec![
        (lab("7_pt_1.eac3"), "eac3", "ec-3", 8, 48000),
        (lab("Canyon-5.1-48khz-448kbit.ac3"), "ac3", "ac-3", 6, 48000),
        (lab("surround51.flac"), "flac", "flac", 6, 48000),
        (lab("surround71.flac"), "flac", "flac", 8, 48000),
        (fixture("tone51.ac3"), "ac3", "ac-3", 6, 48000),
        (fixture("tone51.eac3"), "eac3", "ec-3", 6, 48000),
        (fixture("eac3-joc-lab.eac3"), "eac3", "ec-3", 6, 48000),
        (fixture("sine71.flac"), "flac", "flac", 8, 48000),
        (fixture("stereo-s24.flac"), "flac", "flac", 2, 48000),
        (fixture("tone51.dts"), "dts", "dtsc", 6, 48000),
        (fixture("dtshd-ma-lab.dts"), "dts", "dtsl", 6, 48000),
        (fixture("tone51.thd"), "truehd", "mlpa", 6, 48000),
        (fixture("truehd71-lab.thd"), "truehd", "mlpa", 8, 48000),
        (fixture("tone51.mlp"), "mlp", "mlpa", 6, 48000),
        (fixture("sine71-s24.wav"), "wav", "pcm-s24le", 8, 48000),
        (fixture("sine71-s24-rf64.wav"), "wav", "pcm-s24le", 8, 48000),
        (fixture("sine51-f32.wav"), "wav", "pcm-f32le", 6, 48000),
        (fixture("stereo-s16.wav"), "wav", "pcm-s16le", 2, 48000),
        (fixture("sine71-s32.w64"), "wav", "pcm-s32le", 8, 48000),
        (fixture("stereo.aac"), "aac", "mp4a.40.2", 2, 48000),
        (fixture("tone51.aac"), "aac", "mp4a.40.2", 6, 48000),
    ]
}

fn check_packets(d: &Demuxer, want: &[Probe], name: &str) {
    let t = &d.tracks()[0];
    let scale = f64::from(t.timescale);
    let got: Vec<&PacketRef> = d.packets().iter().collect();
    assert_eq!(got.len(), want.len(), "{name}: packet count");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert_eq!((g.offset, g.size), (w.pos, w.size), "{name}: packet {i} position and size");
        assert!((g.pts as f64 / scale - w.pts_s).abs() < 2e-6, "{name}: packet {i} pts {} vs {}", g.pts as f64 / scale, w.pts_s);
        assert!((g.duration as f64 / scale - w.dur_s).abs() < 2e-6, "{name}: packet {i} duration {} vs {}", g.duration as f64 / scale, w.dur_s);
        assert_eq!(g.keyframe, w.key, "{name}: packet {i} key flag");
    }
}

#[test]
fn packets_equal_ffprobe_eager() {
    for (path, codec, cstr, channels, rate) in cases() {
        if !have(&path) {
            eprintln!("skip {path}");
            continue;
        }
        let Some(want) = ffprobe(&path) else {
            eprintln!("no ffprobe");
            return;
        };
        let src = FileSource::open(&path).unwrap();
        let d = Demuxer::open(&src).unwrap_or_else(|e| panic!("{path}: {e}"));
        assert_eq!(d.container(), Container::Raw, "{path}");
        let [t] = d.tracks() else { panic!("{path}: one track") };
        assert_eq!(t.kind, TrackKind::Audio);
        assert_eq!((t.codec.as_str(), t.codec_string.as_deref()), (codec, Some(cstr)), "{path}");
        assert_eq!((t.channels, t.sample_rate, t.timescale), (Some(channels), Some(rate), rate), "{path}");
        assert!(d.is_complete());
        check_packets(&d, &want, &path);
        // Payload bytes are the file bytes.
        let p = &d.packets()[d.packets().len() / 2];
        let mut buf = Vec::new();
        d.read_packet(&src, p, &mut buf).unwrap();
        let mut direct = vec![0u8; p.size as usize];
        src.read_at(p.offset, &mut direct).unwrap();
        assert_eq!(buf, direct);
        // The duration is the end of the last packet.
        let last = d.packets().last().unwrap();
        let end_ns = (last.pts + last.duration) as u128 * 1_000_000_000 / u128::from(rate);
        assert_eq!(d.duration_ns().map(u128::from), Some(end_ns), "{path}: duration");
    }
}

#[test]
fn lazy_open_reads_little_and_indexes_to_the_same_list() {
    for (path, ..) in cases() {
        if !have(&path) {
            continue;
        }
        let Some(want) = ffprobe(&path) else { return };
        let file = FileSource::open(&path).unwrap();
        let src = Counting { inner: &file, bytes: Cell::new(0) };
        let mut d = Demuxer::open_lazy(&src).unwrap();
        let opened = src.bytes.get();
        assert!(opened <= 1 << 20, "{path}: open read {opened} bytes");
        assert!(!d.packets().is_empty());
        if file.len() > 4 << 20 {
            assert!(!d.is_complete(), "{path}: lazy open of a large file is partial");
            let est = d.duration_ns().expect("duration estimate");
            let exact = want.last().map(|l| (l.pts_s + l.dur_s) * 1e9).unwrap();
            // Constant bit rate streams are close; the VBR ones within a few tens of percent.
            assert!((est as f64 - exact).abs() / exact < 0.35, "{path}: estimate {est} vs {exact}");
        }
        let mut guard = 0;
        while !d.is_complete() {
            d.index_more(&src, 1 << 20).unwrap();
            guard += 1;
            assert!(guard < 10_000);
        }
        check_packets(&d, &want, &path);
    }
}

#[test]
fn seek_lands_at_or_before_the_target_and_keeps_a_continuous_timeline() {
    for (path, ..) in cases() {
        if !have(&path) {
            continue;
        }
        let Some(want) = ffprobe(&path) else { return };
        let file = FileSource::open(&path).unwrap();
        if file.len() < 1 << 20 {
            continue;
        }
        let mut d = Demuxer::open_lazy(&file).unwrap();
        let track = d.tracks()[0].clone();
        let scale = f64::from(track.timescale);
        let total_s = want.last().map(|l| l.pts_s + l.dur_s).unwrap();
        for frac in [0.5, 0.9, 0.2, 0.0, 0.97] {
            let target_s = total_s * frac;
            let target = (target_s * scale) as i64;
            let i = d.seek_to(&file, track.id, target).unwrap_or_else(|e| panic!("{path}: seek {frac}: {e}"));
            let p = d.packets()[i].clone();
            assert!(p.keyframe, "{path}: lands on a key packet");
            assert!(p.pts <= target, "{path}: pts {} after target {target}", p.pts);
            // The landing packet exists at that byte position in the real list and the time is close
            // (exact for PCM and FLAC, within the model error for the others).
            let real = want.iter().find(|w| w.pos == p.offset).unwrap_or_else(|| panic!("{path}: no real packet at {}", p.offset));
            let err = (p.pts as f64 / scale - real.pts_s).abs();
            let exact = matches!(track.codec.as_str(), "wav" | "flac");
            // Lossless TrueHD / MLP rates swing with the content, the other streams are close to constant rate.
            // A file small enough to be reached by growing the indexed head counts samples from the start: within one frame.
            let tolerance = if exact { 1e-6 } else if file.len() <= 16 << 20 { f64::from(p.duration as i32) / scale } else if matches!(track.codec.as_str(), "truehd" | "mlp") { total_s * 0.25 + 1.0 } else { total_s * 0.05 + 0.5 };
            eprintln!("{path}: frac {frac} timestamp error {err:.3} s of {total_s:.1}");
            assert!(err <= tolerance, "{path}: frac {frac} landed with timestamp error {err} s");
            // Walking forward from there stays contiguous in storage and time.
            let mut prev = p;
            for q in d.packets()[i + 1..].iter().take(200) {
                if q.offset != prev.offset + u64::from(prev.size) {
                    break;
                }
                assert_eq!(q.pts, prev.pts + prev.duration, "{path}: timeline break at {}", q.offset);
                prev = q.clone();
            }
        }
        // After all of that the indexing can still be completed and then equals the real list.
        d.index_all(&file).unwrap();
        assert!(d.is_complete());
        if matches!(track.codec.as_str(), "wav" | "flac") {
            check_packets(&d, &want, &path);
        } else {
            assert_eq!(d.packets().len(), want.len(), "{path}: packet count after seeks and index_all");
            let mut sorted = d.packets().to_vec();
            sorted.sort_by_key(|p| p.offset);
            assert!(sorted.iter().zip(d.packets()).all(|(a, b)| a.offset == b.offset), "storage order");
            for w in d.packets().windows(2) {
                assert_eq!(w[1].pts, w[0].pts + w[0].duration, "{path}: joined regions are continuous at {}", w[1].offset);
            }
        }
    }
}

#[test]
fn flac_exposes_streaminfo_as_description_and_uses_the_seek_table() {
    let path = format!("{LAB}/surround71.flac");
    if !have(&path) {
        return;
    }
    let src = FileSource::open(&path).unwrap();
    let d = Demuxer::open(&src).unwrap();
    let t = &d.tracks()[0];
    assert_eq!(&t.codec_private[..4], b"fLaC");
    assert_eq!(t.codec_private[4], 0x80);
    assert_eq!(t.codec_private.len(), 4 + 4 + 34);
    assert_eq!(t.bit_depth, Some(16));
    assert_eq!(d.duration_ns(), Some(16_000_000_000));
}

#[test]
fn wav_keeps_the_channel_mask_in_codec_private() {
    let path = fixture("sine71-s24.wav");
    if !have(&path) {
        return;
    }
    let src = FileSource::open(&path).unwrap();
    let d = Demuxer::open_lazy(&src).unwrap();
    let t = &d.tracks()[0];
    assert_eq!(t.codec_private.len(), 40);
    assert_eq!(u16::from_le_bytes([t.codec_private[0], t.codec_private[1]]), 0xfffe);
    assert_eq!(u32::from_le_bytes(t.codec_private[20..24].try_into().unwrap()), 0x63f, "7.1 mask");
    assert_eq!(t.bit_depth, Some(24));
}

#[test]
fn other_containers_keep_their_detection_and_junk_stays_unrecognised() {
    let dir = format!("{}/tests/fixtures", env!("CARGO_MANIFEST_DIR"));
    let mut seen = 0;
    // The media are generated (tests/fixtures/generate*.sh) and git-ignored; the junk checks below run regardless.
    for e in std::fs::read_dir(&dir).into_iter().flatten().flatten().filter(|e| e.path().is_file()) {
        let name = e.file_name().to_string_lossy().into_owned();
        let want = match name.rsplit('.').next() {
            Some("mp4" | "mov") => Container::Mp4,
            Some("mkv") => Container::Matroska,
            Some("ts" | "m2ts") => Container::MpegTs,
            _ => continue,
        };
        let src = FileSource::open(e.path()).unwrap();
        assert_eq!(Demuxer::open_lazy(&src).unwrap().container(), want, "{name}");
        seen += 1;
    }
    if seen == 0 {
        eprintln!("skip container detection: no media in {dir} (run tests/fixtures/generate.sh)");
    } else {
        assert!(seen > 5);
    }
    // Junk, including streams that merely start with a sync word, is not a raw file.
    let mut junk = vec![0u8; 100_000];
    for (i, b) in junk.iter_mut().enumerate() {
        *b = (i.wrapping_mul(2654435761) >> 7) as u8;
    }
    for head in [&[0x0b, 0x77, 0x12, 0x34][..], &[0x7f, 0xfe, 0x80, 0x01], &[0xff, 0xf1, 0x4c, 0x80], b"fLaC", b"RIFF\0\0\0\0WAVE", b"DTSHDHDR"] {
        let mut v = junk.clone();
        v[..head.len()].copy_from_slice(head);
        assert!(Demuxer::open_lazy(&SliceSource(&v)).is_err(), "junk with head {head:02x?}");
    }
    assert!(Demuxer::open_lazy(&SliceSource(&junk)).is_err());
    assert!(Demuxer::open_lazy(&SliceSource(&[])).is_err());
}
